<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Bukti {{ sprintf('TS-%06d', $transaction->id) }}</title>
<style>body{font:15px Arial,sans-serif;color:#1e293b;background:#f1f5f9;margin:0;padding:32px}.receipt{max-width:680px;margin:auto;background:#fff;border:1px solid #cbd5e1;padding:36px}h1{font-size:24px;margin:8px 0}h2{font-size:16px}p{line-height:1.6}.muted{color:#64748b}.amount{padding:20px;background:#f0fdf4;font-size:26px;font-weight:bold;margin:24px 0}table{width:100%;border-collapse:collapse}td{padding:10px 0;vertical-align:top;border-bottom:1px solid #e2e8f0}td:first-child{width:38%;color:#64748b}.signatures{display:flex;justify-content:space-between;text-align:center;margin-top:36px}.signature{width:45%}.name{margin-top:70px}button{cursor:pointer;padding:12px 20px;border:0;border-radius:8px;background:#4f46e5;color:white;margin-bottom:20px}@media print{body{background:white;padding:0}.receipt{border:0;max-width:none;padding:16px}.no-print{display:none}@page{size:A5;margin:12mm}}@media(max-width:500px){body{padding:12px}.receipt{padding:20px}.amount{font-size:22px}}</style></head>
<body><div class="receipt"><button class="no-print" onclick="window.print()">Cetak / Simpan PDF</button><p class="muted">{{ $school }}</p><h1>Bukti {{ $transaction->jenis === 'masuk' ? 'Setoran' : 'Penarikan' }} Tabungan</h1><p class="muted">No. {{ sprintf('TS-%06d', $transaction->id) }}</p><div class="amount">Rp {{ number_format($transaction->jumlah, 0, ',', '.') }}</div><table><tr><td>Tanggal transaksi</td><td>{{ $transaction->tanggal->format('d/m/Y') }}</td></tr><tr><td>Nama siswa</td><td><strong>{{ $transaction->siswa?->nama ?? '-' }}</strong></td></tr><tr><td>NIS / Kelas</td><td>{{ $transaction->siswa?->nis ?? '-' }} / {{ $transaction->siswa?->kelas?->nama_kelas ?? '-' }}</td></tr><tr><td>Keterangan</td><td>{{ $transaction->keterangan ?: '-' }}</td></tr></table><div class="signatures"><div class="signature"><p>Siswa / Wali</p><p class="name">{{ $transaction->siswa?->nama }}</p></div><div class="signature"><p>Pengelola tabungan</p><p class="name">{{ $teacher }}</p></div></div><p class="muted" style="font-size:11px;margin-top:28px">Dicetak {{ now()->format('d/m/Y H:i') }} · Simpan sebagai bukti transaksi.</p></div></body></html>
